<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';$error='';$success='';
$allowed=['site_title','contact_email','contact_phone','instagram_url','linkedin_url','about_text'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO app_settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');foreach($allowed as $key){$value=trim((string)($_POST[$key]??''));if(in_array($key,['instagram_url','linkedin_url'],true)&&$value!==''&&!filter_var($value,FILTER_VALIDATE_URL))throw new RuntimeException('Sosial şəbəkə linki düzgün URL olmalıdır.');$q->execute([$key,$value]);}$pdo->commit();$success='Parametrlər yadda saxlanıldı.';}catch(Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$error=$x instanceof PDOException?'Parametrlər saxlanılmadı.':$x->getMessage();}}
$settings=$pdo->query('SELECT setting_key,setting_value FROM app_settings')->fetchAll(PDO::FETCH_KEY_PAIR);admin_header('Parametrlər','settings');?>
<?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="notice success"><?=e($success)?></div><?php endif;?>
<div class="content-grid"><section class="panel"><div class="panel-head"><div><small>SAYT MƏLUMATLARI</small><h2>Ümumi parametrlər</h2></div></div><form class="admin-form" method="post"><?=csrf_field()?><label>Saytın adı<input name="site_title" maxlength="180" value="<?=e($settings['site_title']??'RashadFinance')?>"></label><label>Əlaqə e-maili<input type="email" name="contact_email" maxlength="190" value="<?=e($settings['contact_email']??'')?>"></label><label>Telefon<input name="contact_phone" maxlength="60" value="<?=e($settings['contact_phone']??'')?>"></label><label>Instagram URL<input type="url" name="instagram_url" value="<?=e($settings['instagram_url']??'')?>"></label><label>LinkedIn URL<input type="url" name="linkedin_url" value="<?=e($settings['linkedin_url']??'')?>"></label><label>Haqqımda mətni<textarea name="about_text" rows="6"><?=e($settings['about_text']??'')?></textarea></label><button class="btn-admin">Parametrləri yadda saxla</button></form></section>
<section class="panel"><div class="panel-head"><div><small>AI ASSISTANT</small><h2>Chatbot konfiqurasiyası</h2></div></div><p class="muted-copy">Chatbot API açarı serverdə OPENAI_API_KEY mühit dəyişəni kimi saxlanmalıdır. Təhlükəsizlik üçün açar bu paneldə və ya verilənlər bazasında göstərilmir.</p><div class="setting-row"><span>API açarı</span><b><?=!empty($config['openai']['api_key'])?'Serverdə təyin edilib':'Təyin edilməyib'?></b></div><div class="setting-row"><span>Model</span><b><?=e($config['openai']['model']??'gpt-4.1-mini')?></b></div><div class="setting-row"><span>Qeyd</span><b>Yalnız server tərəfi</b></div><p class="muted-copy">API açarını GitHub-a, JavaScript fayllarına və mobil tətbiqə yerləşdirməyin.</p></section></div><?php admin_footer();?>